from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = 10**30
        pairs = [(a, b) for a in range(3) for b in range(3) if a != b]

        dp = {
            (a, b): cost[0][a] + cost[n - 1][b]
            for a, b in pairs
        }

        for i in range(1, n // 2):
            ndp = {}
            for a, b in pairs:
                cur = cost[i][a] + cost[n - 1 - i][b]
                ndp[(a, b)] = min(
                    dp[(pa, pb)] + cur
                    for pa, pb in pairs
                    if a != pa and b != pb
                )
            dp = ndp

        return min(dp.values())
